from pathlib import Path

p = Path("app/src/main/cpp/bassmidi_player.cpp")
s = p.read_text(encoding="utf-8")

old = '''    // 6) Final fallback is conservative: a piano-family Program 0 only.\n    best = nullptr;\n    for (const auto& p : melodyPresetCache_) {\n        std::string pn = p.name;\n        std::transform(pn.begin(), pn.end(), pn.begin(),\n                       [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });\n        if (p.program == 0 && category(pn) == 4) {\n            if (p.bank == requestedSourceBank) {\n                best = &p;\n                break;\n            }\n            if (!best) best = &p;\n        }\n    }\n    if (!best) {\n        LOGI("VOICE RESOLVE no safe primary candidate requestedBank=%d prog=%d name='%s'",\n             requestedBank, requestedProgram, voiceName.c_str());\n        return false;\n    }\n\n    sourceBank = best->bank;\n    sourceProgram = best->program;\n    matchedName = best->name;\n    LOGI("VOICE RESOLVE conservative piano fallback requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s'",\n         requestedBank, requestedProgram, voiceName.c_str(),\n         sourceBank, sourceProgram, matchedName.c_str());\n    return true;\n'''

new = '''    // 6) Category-preserving fallback across the primary SF2.\n    // Never turn a non-piano request into Grand Piano merely because the\n    // requested Yamaha variation bank is absent. Search the whole primary\n    // inventory for the requested family first.\n    if (wantedCategory != 0) {\n        best = nullptr;\n        bestScore = -1;\n        for (const auto& p : melodyPresetCache_) {\n            std::string pn = p.name;\n            std::transform(pn.begin(), pn.end(), pn.begin(),\n                           [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });\n            if (category(pn) != wantedCategory) continue;\n\n            int score = 1000;\n            if (p.bank == requestedSourceBank) score += 120;\n            score += std::max(0, 64 - std::abs(p.program - requestedProgram));\n            if (!lower.empty() && pn.find(lower) != std::string::npos) score += 300;\n\n            if (score > bestScore) {\n                bestScore = score;\n                best = &p;\n            }\n        }\n\n        if (best) {\n            sourceBank = best->bank;\n            sourceProgram = best->program;\n            matchedName = best->name;\n            LOGI("VOICE RESOLVE category fallback requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s' category=%d score=%d",\n                 requestedBank, requestedProgram, voiceName.c_str(),\n                 sourceBank, sourceProgram, matchedName.c_str(),\n                 wantedCategory, bestScore);\n            return true;\n        }\n    }\n\n    // 7) Piano is a valid last resort only when the requested voice itself\n    // belongs to the piano family. Other categories must remain unresolved\n    // so the controlled secondary SF2 can get the next chance.\n    if (wantedCategory != 4) {\n        LOGI("VOICE RESOLVE no category-safe primary candidate requestedBank=%d prog=%d name='%s' category=%d",\n             requestedBank, requestedProgram, voiceName.c_str(), wantedCategory);\n        return false;\n    }\n\n    best = nullptr;\n    for (const auto& p : melodyPresetCache_) {\n        std::string pn = p.name;\n        std::transform(pn.begin(), pn.end(), pn.begin(),\n                       [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });\n        if (p.program == 0 && category(pn) == 4) {\n            if (p.bank == requestedSourceBank) {\n                best = &p;\n                break;\n            }\n            if (!best) best = &p;\n        }\n    }\n    if (!best) {\n        LOGI("VOICE RESOLVE no safe primary candidate requestedBank=%d prog=%d name='%s'",\n             requestedBank, requestedProgram, voiceName.c_str());\n        return false;\n    }\n\n    sourceBank = best->bank;\n    sourceProgram = best->program;\n    matchedName = best->name;\n    LOGI("VOICE RESOLVE conservative piano fallback requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s'",\n         requestedBank, requestedProgram, voiceName.c_str(),\n         sourceBank, sourceProgram, matchedName.c_str());\n    return true;\n'''

if old not in s:
    raise SystemExit("expected resolver fallback block not found; refusing to modify source")
s = s.replace(old, new, 1)

old_alias = '''        if (n.find("brass") != std::string::npos ||\n            n.find("trumpet") != std::string::npos ||\n            n.find("trombone") != std::string::npos) return 7;'''
new_alias = '''        if (n.find("brass") != std::string::npos ||\n            n.find("trumpet") != std::string::npos ||\n            n.find("trombone") != std::string::npos ||\n            n.find("horn") != std::string::npos) return 7;'''
if old_alias not in s:
    raise SystemExit("expected brass category block not found; refusing to modify source")
s = s.replace(old_alias, new_alias, 1)

# V3 test: when the primary SF2 has a semantic candidate, compare it against
# the controlled secondary SF2 before returning. Exact bank/program matches
# still returned earlier and therefore remain authoritative.
old_semantic_return = '''    if (best && bestScore >= 1000) {\n        sourceBank = best->bank;\n        sourceProgram = best->program;\n        matchedName = best->name;\n        LOGI("VOICE RESOLVE semantic requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s' score=%d category=%d",\n             requestedBank, requestedProgram, voiceName.c_str(),\n             sourceBank, sourceProgram, matchedName.c_str(),\n             bestScore, wantedCategory);\n        return true;\n    }'''
new_semantic_return = '''    if (best && bestScore >= 1000) {\n        // Compare the same semantic request against the secondary SF2. A\n        // primary candidate must not win merely because it is checked first.\n        const MelodicPresetEntry* primaryBest = best;\n        const int primaryScore = bestScore;\n        const MelodicPresetEntry* secondaryBest = nullptr;\n        int secondaryScore = -1;\n        for (const auto& p : melodyFallbackPresetCache_) {\n            std::string pn = p.name;\n            std::transform(pn.begin(), pn.end(), pn.begin(),\n                           [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });\n            const int candidateCategory = category(pn);\n            if (wantedCategory != 0 && candidateCategory != wantedCategory) continue;\n            int score = 1000;\n            if (p.bank == requestedSourceBank) score += 80;\n            if (!lower.empty() && pn == lower) score += 1500;\n            if (!lower.empty() && pn.find(lower) != std::string::npos) score += 350;\n            score += std::max(0, 64 - std::abs(p.program - requestedProgram));\n            if (score > secondaryScore) {\n                secondaryScore = score;\n                secondaryBest = &p;\n            }\n        }\n\n        if (secondaryBest && secondaryScore > primaryScore) {\n            sourceBank = secondaryBest->bank;\n            sourceProgram = secondaryBest->program;\n            matchedName = secondaryBest->name;\n            sourceFont = 1;\n            LOGI("VOICE RESOLVE semantic secondary requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s' score=%d category=%d",\n                 requestedBank, requestedProgram, voiceName.c_str(),\n                 sourceBank, sourceProgram, matchedName.c_str(),\n                 secondaryScore, wantedCategory);\n            return true;\n        }\n\n        sourceBank = primaryBest->bank;\n        sourceProgram = primaryBest->program;\n        matchedName = primaryBest->name;\n        LOGI("VOICE RESOLVE semantic requestedBank=%d prog=%d name='%s' -> bank=%d prog=%d '%s' score=%d category=%d",\n             requestedBank, requestedProgram, voiceName.c_str(),\n             sourceBank, sourceProgram, matchedName.c_str(),\n             primaryScore, wantedCategory);\n        return true;\n    }'''
if old_semantic_return not in s:
    raise SystemExit("expected semantic return block not found; refusing to modify source")
s = s.replace(old_semantic_return, new_semantic_return, 1)

p.write_text(s, encoding="utf-8")
print("Applied multi-SF2 category-preserving resolver test patch")
